```ruby
# app.rb
require 'sinatra'
require 'httparty'
require 'json'
require 'date'

class PrivatBankExchangeRates < Sinatra::Base
  set :public_folder, File.dirname(__FILE__) + '/public'
  set :bind, '0.0.0.0'

  # PrivatBank API endpoint for cash exchange rates
  PRIVATBANK_API_URL = 'https://api.privatbank.ua/p24api/pubinfo?json&exchange&coursid=5'

  # Helper method to fetch exchange rates from PrivatBank API
  def fetch_exchange_rates
    response = HTTParty.get(PRIVATBANK_API_URL)

    if response.success?
      JSON.parse(response.body)
    else
      raise "Failed to fetch exchange rates: #{response.code} - #{response.message}"
    end
  end

  # Helper method to format currency display
  def format_currency(amount)
    sprintf('%.2f', amount.to_f)
  end

  # Helper method to get current date and time
  def current_datetime
    Time.now.strftime('%Y-%m-%d %H:%M:%S')
  end

  # Main route - displays exchange rates
  get '/' do
    begin
      @rates = fetch_exchange_rates
      @last_updated = current_datetime
      @error = nil
    rescue StandardError => e
      @rates = []
      @error = e.message
      @last_updated = current_datetime
    end

    erb :index
  end

  # API endpoint that returns JSON data
  get '/api/rates' do
    content_type :json

    begin
      rates = fetch_exchange_rates
      {
        success: true,
        last_updated: current_datetime,
        rates: rates
      }.to_json
    rescue StandardError => e
      {
        success: false,
        error: e.message,
        last_updated: current_datetime
      }.to_json
    end
  end
end

# Start the application
if __FILE__ == $0
  PrivatBankExchangeRates.run!
end
