```ruby
# app.rb
require 'sinatra'
require 'httparty'
require 'json'

class CurrencyApp < Sinatra::Base
  # Головна сторінка з курсами валют
  get '/' do
    @rates = get_exchange_rates
    erb :index
  end

  # API endpoint для отримання курсів у форматі JSON
  get '/api/rates' do
    content_type :json
    get_exchange_rates.to_json
  end

  private

  def get_exchange_rates
    begin
      # Отримання даних з API ПриватБанку
      response = HTTParty.get('https://api.privatbank.ua/p24api/pubinfo?json&exchange&coursid=5')

      if response.success?
        rates = JSON.parse(response.body)

        # Фільтруємо тільки готівкові курси (валюти, що доступні в касах)
        cash_rates = rates.select { |rate| rate['ccy'] && rate['base_ccy'] }

        # Додаємо українські назви валют
        currency_names = {
          'USD' => 'Долар США',
          'EUR' => 'Євро',
          'RUR' => 'Російський рубль',
          'BTC' => 'Біткойн'
        }

        cash_rates.map do |rate|
          {
            currency: rate['ccy'],
            currency_name: currency_names[rate['ccy']] || rate['ccy'],
            base_currency: rate['base_ccy'],
            buy: rate['buy'].to_f.round(2),
            sale: rate['sale'].to_f.round(2)
          }
        end
      else
        # У випадку помилки повертаємо пустий масив
        []
      end
    rescue StandardError => e
      puts "Помилка при отриманні курсів: #{e.message}"
      []
    end
  end
end
```

