# delivery_status.rb
require 'httparty'
require 'json'
require 'dotenv'

Dotenv.load

class DeliveryService
  include HTTParty

  # Базовий URI API служби доставки (приклад для Nova Poshta)
  base_uri 'https://api.novaposhta.ua/v2.0/json'

  def initialize(api_key = nil)
    @api_key = api_key || ENV['DELIVERY_API_KEY']
    @options = {
      headers: {
        'Content-Type' => 'application/json'
      }
    }
  end

  # Отримати статус доставки за номером накладної
  def get_delivery_status(tracking_number)
    request_body = {
      apiKey: @api_key,
      modelName: 'TrackingDocument',
      calledMethod: 'getStatusDocuments',
      methodProperties: {
        Documents: [
          {
            DocumentNumber: tracking_number,
            Phone: '' # Опціонально: номер телефону отримувача
          }
        ]
      }
    }

    response = self.class.post('', @options.merge(body: request_body.to_json))

    if response.success?
      parse_status_response(response)
    else
      { error: "Помилка запиту: #{response.code} - #{response.message}" }
    end
  end

  # Отримати інформацію про відділення за номером
  def get_warehouse_info(warehouse_ref)
    request_body = {
      apiKey: @api_key,
      modelName: 'Address',
      calledMethod: 'getWarehouses',
      methodProperties: {
        Ref: warehouse_ref
      }
    }

    response = self.class.post('', @options.merge(body: request_body.to_json))

    if response.success?
      parse_warehouse_response(response)
    else
      { error: "Помилка запиту: #{response.code} - #{response.message}" }
    end
  end

  private

  def parse_status_response(response)
    data = JSON.parse(response.body)

    if data['success']
      document_info = data['data'].first

      {
        tracking_number: document_info['Number'],
        status: document_info['Status'],
        status_code: document_info['StatusCode'],
        warehouse_sender: document_info['WarehouseSender'],
        warehouse_recipient: document_info['WarehouseRecipient'],
        estimated_delivery: document_info['EstimatedDeliveryDate'],
        actual_delivery: document_info['ActualDeliveryDate'],
        created_date: document_info['DateCreated'],
        weight: document_info['Weight'],
        cost: document_info['Cost'],
        recipient_full_name: document_info['RecipientFullName']
      }
    else
      { error: data['errors'].join(', ') }
    end
  end

  def parse_warehouse_response(response)
    data = JSON.parse(response.body)

    if data['success']
      warehouse = data['data'].first

      {
        description: warehouse['Description'],
        city: warehouse['CityDescription'],
        address: warehouse['ShortAddress'],
        schedule: warehouse['Schedule'],
        phone: warehouse['Phone']
      }
    else
      { error: data['errors'].join(', ') }
    end
  end
end

