# order_notifier.rb
require 'slack-ruby-client'
require 'logger'

class OrderNotifier
  def initialize(slack_token: nil, channel: '#orders')
    @channel = channel
    @logger = Logger.new($stdout)

    # Configure Slack client
    Slack.configure do |config|
      config.token = slack_token || ENV['SLACK_API_TOKEN']
    end

    @client = Slack::Web::Client.new
    @logger.info("Slack notifier initialized for channel: #{@channel}")
  end

  def notify_new_order(order)
    message = build_order_message(order)

    begin
      response = @client.chat_postMessage(
        channel: @channel,
        text: message[:text],
        attachments: message[:attachments],
        blocks: message[:blocks]
      )

      @logger.info("Order notification sent successfully: #{order[:id]}")
      { success: true, response: response }

    rescue Slack::Web::Api::Errors::SlackError => e
      @logger.error("Failed to send Slack notification: #{e.message}")
      { success: false, error: e.message }
    end
  end

  private

  def build_order_message(order)
    {
      text: "📦 New Order Received!",
      attachments: [
        {
          color: "#36a64f",
          fields: [
            {
              title: "Order ID",
              value: order[:id] || order[:order_id],
              short: true
            },
            {
              title: "Customer",
              value: order[:customer_name] || "N/A",
              short: true
            },
            {
              title: "Amount",
              value: format_amount(order[:amount]),
              short: true
            },
            {
              title: "Items",
              value: order[:item_count].to_s,
              short: true
            },
            {
              title: "Shipping Address",
              value: order[:shipping_address] || "N/A",
              short: false
            }
          ],
          ts: Time.now.to_i
        }
      ],
      blocks: [
        {
          type: "section",
          text: {
            type: "mrkdwn",
            text: "📦 *New Order Received!*"
          }
        },
        {
          type: "section",
          fields: [
            {
              type: "mrkdwn",
              text: "*Order ID:*\n#{order[:id] || order[:order_id]}"
            },
            {
              type: "mrkdwn",
              text: "*Customer:*\n#{order[:customer_name] || 'N/A'}"
            },
            {
              type: "mrkdwn",
              text: "*Amount:*\n#{format_amount(order[:amount])}"
            },
            {
              type: "mrkdwn",
              text: "*Items:*\n#{order[:item_count]}"
            }
          ]
        },
        {
          type: "section",
          text: {
            type: "mrkdwn",
            text: "*Shipping Address:*\n#{order[:shipping_address] || 'N/A'}"
          }
        },
        {
          type: "divider"
        }
      ]
    }
  end

  def format_amount(amount)
    if amount.is_a?(Numeric)
      "$#{'%.2f' % amount}"
    else
      amount.to_s
    end
  end
end

