require 'httparty'
require 'json'

class TeamsWebhook
  def initialize(webhook_url)
    @webhook_url = webhook_url
    validate_webhook_url
  end

  # Основний метод для відправки повідомлення
  def send_message(message, options = {})
    payload = build_payload(message, options)
    send_webhook(payload)
  end

  # Метод для відправки простого текстового повідомлення
  def send_text_message(text, title = nil)
    payload = {
      "@type" => "MessageCard",
      "@context" => "http://schema.org/extensions",
      "themeColor" => "0076D7",
      "summary" => title || "Notification",
      "sections" => [{
        "activityTitle" => title,
        "text" => text
      }]
    }.compact

    send_webhook(payload)
  end

  # Метод для відправки повідомлення з кнопкою дії
  def send_message_with_action(text, title, button_text, button_url)
    payload = {
      "@type" => "MessageCard",
      "@context" => "http://schema.org/extensions",
      "themeColor" => "0076D7",
      "summary" => title,
      "sections" => [{
        "activityTitle" => title,
        "text" => text
      }],
      "potentialAction" => [{
        "@type" => "OpenUri",
        "name" => button_text,
        "targets" => [{
          "os" => "default",
          "uri" => button_url
        }]
      }]
    }

    send_webhook(payload)
  end

  # Метод для відправки повідомлення з фактами (key-value pairs)
  def send_message_with_facts(text, title, facts = {})
    fact_sections = facts.map { |key, value| { "name" => key.to_s, "value" => value.to_s } }

    payload = {
      "@type" => "MessageCard",
      "@context" => "http://schema.org/extensions",
      "themeColor" => "0076D7",
      "summary" => title,
      "sections" => [{
        "activityTitle" => title,
        "text" => text,
        "facts" => fact_sections
      }]
    }

