      fenced_code_blocks: true,
      no_intra_emphasis: true,
      autolink: true,
      strikethrough: true,
      lax_html_blocks: true,
      superscript: true,
      tables: true,
      highlight: true,
      quote: true,
      footnotes: true
    }.merge(options)
  end

  def convert(markdown_text)
    # Створюємо рендерер з нашими кастомними налаштуваннями
    renderer = HTMLWithRouge.new(
      filter_html: true,           # Фільтруємо небезпечний HTML
