Ці геми потрібні для роботи з XML-даними та побудови самого XML-файлу. `nokogiri` — популярний парсер XML і HTML для Ruby, а `builder` дозволяє створювати XML-файли у простому та зручному форматі.

Після оновлення списку гемів за допомогою команди `bundle install`, ви можете використовувати наступний код для генерації XML-файлу SEPA-переказу:

```ruby
require 'builder'

class SepaPayment
  def initialize(payments)
    @payments = payments
  end

  def generate_xml
    xml = Builder::XmlMarkup.new(indent: 2)
    xml.instruct!
    xml.Document {
      xml.CstmrCdtTrfInitn {
        xml.GrpHdr {
          xml.MsgId 'MSG-12345'
          xml.CreDtTime Time.now.strftime('%Y-%m-%dT%H:%M:%S')
          xml.NbOfTxs @payments.size
          xml.CtrlSum @payments.map { |p| p[:amount] }.sum
          xml.InitgPty {
            xml.Nm 'Your Company Name'
            xml.Id {
              xml.OrgId {
                xml.Othr {
                  xml.Id 'Your Company ID'
                  xml.SchmeNm {
                    xml.Cd 'SEPA'
                  }
                }
              }
            }
          }
        }
        xml.PmtInf {
          xml.PmtInfId 'PAY-12345'
          xml.PmtMtd 'TRF'
          xml.BtchBookg 'true'
          xml.NbOfTxs @payments.size
          xml.CtrlSum @payments.map { |p| p[:amount] }.sum
          xml.PmtTpInf {
            xml.SvcLvl {
              xml.Cd 'SEPA'
            }
          }
          @payments.each do |payment|
            xml.DrctDbtTxInf {
              xml.PmtId {
                xml.EndToEndId payment[:end_to_end_id]
                xml.TxId payment[:transaction_id]
              }
              xml.InstdAgt {
                xml.FinInstnId {
                  xml.BIC payment[:bic]
                }
              }
              xml.Dbtr {
                xml.Nm payment[:debtor_name]
              }
              xml.DbtrAcct {
                xml.Id {
                  xml.IBAN payment[:iban]
                }
              }
              xml.CdtTrfTx {
                xml.Amt {
                  xml.InstdAmt payment[:amount], currency: 'EUR'
                }
                xml.CdtrAgt {
                  xml.FinInstnId {
                    xml.BIC payment[:creditor_bic]
                  }
                }
                xml.Cdtr {
                  xml.Nm payment[:creditor_name]
                }
                xml.CdtrAcct {
                  xml.Id {
                    xml.IBAN payment[:creditor_iban]
                  }
                }
                xml.RmtInf {
                  xml.Ustrd payment[:remittance_info]
                }
              }
            }
          }
        }
      }
    }
  end
end

