# ups_shipment.rb
require 'httparty'
require 'nokogiri'
require 'xml-simple'
require 'logger'

class UPSShipment
  def initialize(access_key, user_id, password, shipper_number, test_mode = true)
    @access_key = access_key
    @user_id = user_id
    @password = password
    @shipper_number = shipper_number
    @test_mode = test_mode
    @logger = Logger.new(STDOUT)
  end

  def get_shipping_rates(weight, length, width, height)
    # Set up the XML request
    xml_request = {
      'AccessRequest' => {
        'AccessLicenseNumber' => @access_key,
        'UserId' => @user_id,
        'Password' => @password
      },
      'Shipper' => {
        'ShipperNumber' => @shipper_number,
        'ShipperName' => 'Your Company Name',
        'Address' => {
          'AddressLine1' => '123 Main St',
          'City' => 'Anytown',
          'StateCode' => 'CA',
          'PostalCode' => '12345',
          'CountryCode' => 'US'
        }
      },
      'ShipTo' => {
        'Address' => {
          'AddressLine1' => '456 Elm St',
          'City' => 'Othertown',
          'StateCode' => 'NY',
          'PostalCode' => '67890',
          'CountryCode' => 'US'
        }
      },
      'Shipment' => {
        'Description' => 'Test Shipment',
        'ShipperNumber' => @shipper_number,
        'ShipTo' => {
          'Address' => {
            'AddressLine1' => '456 Elm St',
            'City' => 'Othertown',
            'StateCode' => 'NY',
            'PostalCode' => '67890',
            'CountryCode' => 'US'
          }
        },
        'Package' => {
          'Description' => 'Test Package',
          'PackagingType' => {
            'Code' => '02' # UPS Package
          },
          'Dimensions' => {
            'UnitOfMeasurement' => {
              'Code' => 'IN' # Inches
            },
            'Length' => length,
            'Width' => width,
            'Height' => height
          },
          'PackageWeight' => {
            'UnitOfMeasurement' => {
              'Code' => 'LBS' # Pounds
            },
            'Weight' => weight
          }
        },
        'ShipmentServiceOptions' => {
          'RateRequestOption' => {
            'RateRequestOptionType' => {
              'Code' => 'Shop' # Get all available rates
            }
          }
        }
      }
    }

    # Convert the request to XML
    xml = XmlSimple.xml_out(xml_request, { 'RootName' => 'RateRequest', 'AttrPrefix' => true, 'NoAttr' => true })

    # Set up the HTTP request
    url = @test_mode ? 'https://wwwcie.ups.com/ups.app/xml/Rate' : 'https://onlinetools.ups.com/ups.app/xml/Rate'
    headers = {
      'Content-Type' => 'application/x-www-form-urlencoded',
      'Accept' => 'application/xml'
    }

    # Make the request
    response = HTTParty.post(url, headers: headers, body: xml)

    # Parse the response
    if response.success?
      @logger.info("Successful response from UPS")
      rates = Nokogiri::XML(response.body).xpath('//RateResponse/RatedShipment/RatingService')
      rates.map do |rate|
        {
          service: rate.at('Service').text,
          rate: rate.at('TotalCharges').text
        }
      end
    else
      @logger.error("Error response from UPS: #{response.code}")
      nil
    end
  end
end

