# onfido_api.rb
require 'httparty'
require 'json'

class OnfidoAPI
  BASE_URL = 'https://api.onfido.com/v3'

  def initialize(api_token)
    @api_token = api_token
  end

  def create_applicant(applicant_data)
    response = HTTParty.post(
      "#{BASE_URL}/applicants",
      headers: {
        'Authorization' => "Bearer #{@api_token}",
        'Content-Type' => 'application/json'
      },
      body: applicant_data.to_json
    )

    JSON.parse(response.body)
  end

  def create_document_check(applicant_id, document_data)
    response = HTTParty.post(
      "#{BASE_URL}/applicants/#{applicant_id}/checks",
      headers: {
        'Authorization' => "Bearer #{@api_token}",
        'Content-Type' => 'application/json'
      },
      body: {
        'type' => 'document',
        'reports' => [
          {
            'name' => 'document'
          }
        ],
        'document' => document_data
      }.to_json
    )

    JSON.parse(response.body)
  end

  def create_selfie_check(applicant_id, selfie_data)
    response = HTTParty.post(
      "#{BASE_URL}/applicants/#{applicant_id}/checks",
      headers: {
        'Authorization' => "Bearer #{@api_token}",
        'Content-Type' => 'application/json'
      },
      body: {
        'type' => 'facial_similarity',
        'reports' => [
          {
            'name' => 'facial_similarity'
          }
        ],
        'facial_similarity' => selfie_data
      }.to_json
    )

    JSON.parse(response.body)
  end

  def retrieve_check_status(check_id)
    response = HTTParty.get(
      "#{BASE_URL}/checks/#{check_id}",
      headers: {
        'Authorization' => "Bearer #{@api_token}"
      }
    )

    JSON.parse(response.body)
  end
end

# Example usage
if __FILE__ == $0
  api_token = 'YOUR_ONFIDO_API_TOKEN'
  onfido_api = OnfidoAPI.new(api_token)

  # Create an applicant
  applicant_data = {
    'first_name' => 'John',
    'last_name' => 'Doe',
    'email' => 'johndoe@example.com'
  }
  applicant = onfido_api.create_applicant(applicant_data)
  applicant_id = applicant['id']

  # Create a document check
  document_data = {
    'type' => 'passport',
    'side' => 'front',
    'file' => 'base64 encoded file contents'
  }
  document_check = onfido_api.create_document_check(applicant_id, document_data)
  document_check_id = document_check['id']

  # Create a selfie check
  selfie_data = {
    'file' => 'base64 encoded file contents'
  }
  selfie_check = onfido_api.create_selfie_check(applicant_id, selfie_data)
  selfie_check_id = selfie_check['id']

  # Retrieve the status of the checks
  document_check_status = onfido_api.retrieve_check_status(document_check_id)
  selfie_check_status = onfido_api.retrieve_check_status(selfie_check_id)

  puts "Document check status: #{document_check_status['status']}"
  puts "Selfie check status: #{selfie_check_status['status']}"
end
```

**Note:**

* Replace `'YOUR_ONFIDO_API_TOKEN'` with your actual Onfido API token.
* The `file` fields in the `document_data` and `selfie_data` hashes should contain the base64 encoded contents of the document and selfie images, respectively.
* The `create_applicant`, `create_document_check`, and `create_selfie_check` methods return the created resources' IDs, which can be used to retrieve their status later.
* The `retrieve_check_status` method returns the status of the specified check, which can be one of `'awaiting_data'`, `'in_progress'`, `'complete'`, or `'paused'`.

