## Реалізація коду

```ruby
require 'httparty'
require 'json'

class UPSRateCalculator
  include HTTParty
  base_uri 'onlinetools.ups.com'

  API_KEY = 'YOUR_API_KEY' # Замініть на свій API ключ UPS
  USER_ID = 'YOUR_USER_ID'  # Замініть на свій User ID UPS
  PASSWORD = 'YOUR_PASSWORD' # Замініть на свій пароль UPS

  def initialize
    @headers = {
      'Content-Type' => 'application/x-www-form-urlencoded',
      'Accept' => 'application/json'
    }
  end

  def calculate_rates(origin, destination, package)
    # Формуємо XML запит для UPS API
    request_xml = build_request_xml(origin, destination, package)

    response = self.class.post(
      '/ship/v1/shipments/rating',
      body: request_xml,
      headers: @headers,
      basic_auth: { username: USER_ID, password: PASSWORD }
    )

    if response.success?
      parse_response(response.body)
    else
      { error: "UPS API Error: #{response.parsed_response['errors'].first['description']}" }
    end
  end

  private

  def build_request_xml(origin, destination, package)
    # Конвертуємо дані в XML форматі, який очікує UPS
    Nokogiri::XML::Builder.new do |xml|
      xml.Request {
        xml.RequestOption { xml.XMLDetail { xml.Detailed { xml.Version { text '2' } } } }

        xml.SubmissionID { text "RateRequest_#{Time.now.to_i}" }

        xml.RateRequest {
          xml.RateRequestControl {
            xml.RequesterID { text 'Rate' }
            xml.RequestID { text '1' }
          }

          xml.RateRequestShipment {
            xml.Shipper {
              xml.Name { text origin[:name] }
              xml.Address {
                xml.AddressLine { text origin[:address1] }
                xml.City { text origin[:city] }
                xml.StateProvinceCode { text origin[:state] }
                xml.PostalCode { text origin[:postal_code] }
                xml.CountryCode { text origin[:country_code] }
              }
            }

            xml.ShipTo {
              xml.Name { text destination[:name] }
              xml.Address {
                xml.AddressLine { text destination[:address1] }
                xml.City { text destination[:city] }
                xml.StateProvinceCode { text destination[:state] }
                xml.PostalCode { text destination[:postal_code] }
                xml.CountryCode { text destination[:country_code] }
              }
            }

            xml.Shipment {
              xml.Package {
                xml.PackagingType { text '02' } # 02 = Customer-Supplied Package
                xml.PackageWeight {
                  xml.UnitOfMeasurement { text package[:weight_unit] || 'LBS' } # або 'KGS'
                  xml.Weight { text package[:weight] }
                }
                xml.Dimensions {
                  xml.UnitOfMeasurement { text package[:dimension_unit] || 'IN' } # або 'CM'
                  xml.Length { text package[:length] }
                  xml.Width { text package[:width] }
                  xml.Height { text package[:height] }
                }
              }
            }

            xml.ShipperNumber { text USPS_ACCOUNT_NUMBER }

            xml.ShipmentServiceOptions {
              xml.SaturdayDeliveryIndicator { text '1' }
            }
          }
        }
      }
    end.to_xml
  end

  def parse_response(response_body)
    # Парсимо відповідь від UPS API
    doc = Nokogiri::XML(response_body)

    rates = []

    doc.xpath('//RatedShipment').each do |rated_shipment|
      service = {
        name: rated_shipment.xpath('./Service/Description').text,
        code: rated_shipment.xpath('./Service/Code').text,
        base_charge: rated_shipment.xpath('./BillingWeight/BillWeight').text,
        total_charge: rated_shipment.xpath('./TotalCharges/MonetaryValue').text,
        currency: rated_shipment.xpath('./TotalCharges/CurrencyCode').text
      }

      rates << service
    end

    { rates: rates }
  end
end
```

