require 'redcarpet'
require 'rouge'
require 'sanitize'

class MarkdownRenderer
  def initialize
    # Configure Redcarpet with our HTML renderer
    @markdown = Redcarpet::Markdown.new(
      MarkdownHTML.new(hard_wrap: true, prettify: false),
      autolink: true,
      tables: true,
      fenced_code_blocks: true,
      strikethrough: true
    )

    # Configure Sanitize to allow only safe HTML
    @sanitizer = Sanitize::Config.new.merged(
      Sanitize::Config::RELAXED.merge(
        elements: %w[br p h1 h2 h3 h4 h5 h6 pre code blockquote ul ol li em strong a img table tr td th],
        attributes: %w[href src title class alt],
        add_attributes: %w[class]
      )
    )
  end

  # Main method to render user input to safe HTML
  def render(input)
    # Convert markdown to HTML
    html = @markdown.render(input)

    # Sanitize the HTML
    sanitized_html = Sanitize.fragment(html, @sanitizer)

    sanitized_html
  end

  # Custom HTML renderer for Redcarpet
  class MarkdownHTML < Redcarpet::Render::HTML
    def block_code(code, language)
      # Use Rouge to highlight code
      lexer = Rouge::Lexer.find(language) || Rouge::Lexers::PlainText
      formatter = Rouge::Formatters::HTML.new(css_class: 'highlight')
      highlighted = lexer.call(formatter).call(code)

      "<pre><code class=\"language-#{language}\">#{highlighted}</code></pre>"
    end

    # Other methods can be overridden here if needed
  end
end
