# Helper function to fetch Poshtomats near a given address from Nova Poshta API
def get_poshtomats_near(address)
  coordinates = get_coordinates(address)
  return [] if coordinates.nil?

  lat, lng = coordinates
  radius = 10000 # meters (10km) - adjust as needed

  url = "https://api.novaposhta.ua/v2/tracking/addresses?key=#{NOVA_POSHTA_API_KEY}&lat=#{lat}&lng=#{lng}&radius=#{radius}&type=POSHTOMAT"

  begin
    response = RestClient.get(url)
    data = JSON.parse(response.body)
    poshtomats = data['success'].map { |poshtomat|
      {
        name: poshtomat['name'],
        address: poshtomat['address'],
        lat: poshtomat['location']['lat'],
        lng: poshtomat['location']['lng']
      }
    }
    poshtomats
  rescue RestClient::ExceptionWithResponse => e
    puts "Error fetching Poshtomats: #{e.response.code} - #{e.response.body}"
    []
  rescue JSON::ParserError => e
    puts "Error parsing JSON: #{e.message}"
    []
  end
end

