      console.log("Connected to Chat channel");
    },
    disconnected: () => {
      console.log("Disconnected from Chat channel");
    },
    received: (data) => {
      console.log("Received data:", data);
      const messageElement = document.createElement("div");
      messageElement.textContent = data.message;
