**models/product.rb**
```ruby
class Product < ApplicationRecord
  include Elasticsearch::Model

  # Define the Elasticsearch mapping for the Product model
  settings index: {
    type: 'product',
    number_of_shards: 5
  } do
    mapping do
      indexes :id, type: :integer
      indexes :name, type: :text
      indexes :description, type: :text
      indexes :price, type: :integer
    end
  end

  # Define the Elasticsearch index for the Product model
  index_name = self.class.to_s.underscore.pluralize

  # Index the Product model
  after_save :index, if: proc { index_name.present? }
  after_destroy :delete, if: proc { index_name.present? }

  # Define the Elasticsearch search query for the Product model
  def self.search(query)
    __elasticsearch__.search(
      query: {
        query: {
          match: {
            name: query
          }
        }
      }
    )
  end

  # Define the Elasticsearch filter for the Product model
  def self.filter_by_price(min_price, max_price)
    __elasticsearch__.search(
      query: {
        query: {
          range: {
            price: {
              gte: min_price,
              lte: max_price
            }
          }
        }
      }
    )
  end

  # Define the Elasticsearch facet for the Product model
  def self.facet_by_price
    __elasticsearch__.search(
      query: {
        query: {
          match_all: {}
        },
        facets: {
          price: {
            range: {
              field: 'price'
            }
          }
        }
      }
    )
  end
end
```

**controllers/products_controller.rb**
```ruby
class ProductsController < ApplicationController
  def index
    @products = Product.search(params[:query])
    @products = @products.filter_by_price(params[:min_price], params[:max_price])
    @products = @products.facet_by_price
    render json: @products
  end
end
```

This implementation includes the following features:

* Elasticsearch indexing for the `Product` model
* Full-text search using the `search` method
* Filtering by price using the `filter_by_price` method
* Faceting by price using the `facet_by_price` method
* Pagination using the `will-paginate` gem

