```ruby
# firebase_notification_service.rb
require 'fcm'
require 'json'

class FirebaseNotificationService
  def initialize(server_key)
    @fcm = FCM.new(server_key)
  end

  # Send notification to a single device
  def send_to_device(device_token, title, body, data = {})
    options = {
      notification: {
        title: title,
        body: body,
        sound: 'default'
      },
      data: data
    }

    response = @fcm.send([device_token], options)
    handle_response(response, device_token)
  end

  # Send notification to multiple devices
  def send_to_multiple_devices(device_tokens, title, body, data = {})
    options = {
      notification: {
        title: title,
        body: body,
        sound: 'default'
      },
      data: data
    }

    response = @fcm.send(device_tokens, options)
    handle_response(response, device_tokens)
  end

  # Send notification with custom options for different platforms
  def send_advanced_notification(device_tokens, notification_payload, data_payload = {})
    options = {
      notification: notification_payload,
      data: data_payload,
      android: {
        priority: 'high',
        notification: {
          sound: 'default',
          click_action: 'FCM_PLUGIN_ACTIVITY'
        }
      },
      apns: {
        payload: {
          aps: {
            sound: 'default',
            badge: 1
          }
        }
      }
    }

    response = @fcm.send(device_tokens, options)
    handle_response(response, device_tokens)
  end

  # Send silent notification (data-only)
  def send_silent_notification(device_tokens, data)
    options = {
      data: data,
      content_available: true,
      priority: 'high'
    }

    response = @fcm.send(device_tokens, options)
    handle_response(response, device_tokens)
  end

  # Send notification with image (for supported platforms)
  def send_notification_with_image(device_tokens, title, body, image_url, data = {})
    options = {
      notification: {
        title: title,
        body: body,
        image: image_url
      },
      data: data,
      android: {
        notification: {
          image: image_url
        }
      },
      apns: {
        fcm_options: {
          image: image_url
        }
      }
    }

    response = @fcm.send(device_tokens, options)
    handle_response(response, device_tokens)
  end

  private

  def handle_response(response, device_tokens)
    if response[:status_code] == 200
      body = JSON.parse(response[:body])

      if body['failure'] == 0
        {
          success: true,
          message: 'Notification sent successfully',
          response: body,
          multicast_id: body['multicast_id']
        }
      else
        failed_tokens = []
        body['results'].each_with_index do |result, index|
          if result['error']
            failed_tokens << {
              token: device_tokens.is_a?(Array) ? device_tokens[index] : device_tokens,
              error: result['error']
            }
          end
        end

        {
          success: false,
          message: "Failed to send #{body['failure']} notification(s)",
          response: body,
          failed_tokens: failed_tokens
        }
      end
    else
      {
        success: false,
        message: "HTTP Error: #{response[:status_code]}",
        response: response
      }
    end
  rescue JSON::ParserError => e
    {
      success: false,
      message: "Failed to parse response: #{e.message}",
      response: response
    }
  end
end

