```ruby
# fcm_notification_service.rb
require 'fcm'
require 'dotenv'
require 'json'

Dotenv.load

class FCMNotificationService
  def initialize
    @fcm = FCM.new(ENV['FIREBASE_SERVER_KEY'])
  end

  # Надсилання сповіщення на один пристрій
  def send_to_device(device_token, title, body, data = {})
    message = {
      to: device_token,
      notification: {
        title: title,
        body: body,
        sound: 'default'
      },
      data: data
    }

    send_message(message)
  end

  # Надсилання сповіщення на кілька пристроїв
  def send_to_multiple_devices(device_tokens, title, body, data = {})
    message = {
      registration_ids: device_tokens,
      notification: {
        title: title,
        body: body,
        sound: 'default'
      },
      data: data
    }

    send_message(message)
  end

  # Надсилання сповіщення тільки з даними (без спливаючого сповіщення)
  def send_data_message(device_token, data)
    message = {
      to: device_token,
      data: data,
      priority: 'high'
    }

    send_message(message)
  end

  # Надсилання сповіщення з кастомними налаштуваннями для iOS
  def send_ios_notification(device_token, title, body, data = {})
    message = {
      to: device_token,
      notification: {
        title: title,
        body: body,
        sound: 'default',
        badge: '1'
      },
      data: data,
      apns: {
        headers: {
          'apns-priority' => '10'
        },
        payload: {
          aps: {
            sound: 'default',
            badge: 1
          }
        }
      }
    }

    send_message(message)
  end

  # Надсилання сповіщення з кастомними налаштуваннями для Android
  def send_android_notification(device_token, title, body, data = {})
    message = {
      to: device_token,
      notification: {
        title: title,
        body: body,
        sound: 'default',
        icon: 'ic_notification',
        color: '#FF0000'
      },
      data: data,
      android: {
        priority: 'high',
        notification: {
          sound: 'default',
          icon: 'ic_notification',
          color: '#FF0000'
        }
      }
    }

    send_message(message)
  end

  # Надсилання сповіщення з умовою (topic)
  def send_to_topic(topic, title, body, data = {})
    message = {
      condition: "'#{topic}' in topics",
      notification: {
        title: title,
        body: body,
        sound: 'default'
      },
      data: data
    }

    send_message(message)
  end

  private

  def send_message(message)
    begin
      response = @fcm.send(message)

      if response[:status_code] == 200
        body = JSON.parse(response[:body])

        if body['success'] > 0
          puts "Успішно надіслано: #{body['success']}"
        end

        if body['failure'] > 0
          puts "Помилки: #{body['failure']}"
          puts "Деталі помилок: #{body['results']}"
        end

        {
          success: true,
          response: body,
          message_id: body['message_id']
        }
      else
        {
          success: false,
          error: "HTTP Error: #{response[:status_code]}",
          response: response
        }
      end
    rescue StandardError => e
      {
        success: false,
        error: e.message
      }
    end
  end
end
