# app/services/diia_notification_service.rb
require 'httparty'
require 'jwt'
require 'active_support/core_ext/hash'
require 'dotenv'
Dotenv.load

class DiiaNotificationService
  include HTTParty

  # Базовий URL API Дії
  base_uri 'https://api.diia.gov.ua'

  def initialize(partner_id: nil, private_key: nil, client_id: nil, client_secret: nil)
    @partner_id = partner_id || ENV['DIIA_PARTNER_ID']
    @private_key = private_key || OpenSSL::PKey::RSA.new(ENV['DIIA_PRIVATE_KEY'])
    @client_id = client_id || ENV['DIIA_CLIENT_ID']
    @client_secret = client_secret || ENV['DIIA_CLIENT_SECRET']
    @access_token = nil
  end

  # Авторизація та отримання токена доступу
  def authenticate
    headers = {
      'Content-Type' => 'application/json'
    }

    body = {
      client_id: @client_id,
      client_secret: @client_secret
    }

    response = self.class.post('/api/v1/auth/acquirer/login', {
      headers: headers,
      body: body.to_json
    })

    if response.success?
      @access_token = response.parsed_response['token']
      true
    else
      false
    end
  end

  # Створення JWT токена для підпису запитів
  def create_jwt_token(payload = {})
    headers = {
      typ: 'JWT',
      alg: 'RS256',
      kid: @partner_id
    }

    payload = {
      iss: @partner_id,
      iat: Time.now.to_i,
      exp: Time.now.to_i + 300, # 5 хвилин
      **payload
    }

    JWT.encode(payload, @private_key, 'RS256', headers)
  end

  # Надсилання push-сповіщення
  def send_push_notification(user_identifier:, title:, message:, data: {})
    # Авторизуємося, якщо ще не авторизовані
    authenticate unless @access_token

    jwt_token = create_jwt_token

    headers = {
      'Content-Type' => 'application/json',
      'Authorization' => "Bearer #{@access_token}",
      'X-Acquirer-Sign' => jwt_token
    }

    body = {
      userIdentifier: user_identifier,
      title: title,
      message: message,
      data: data,
      timestamp: Time.now.iso8601
    }

    response = self.class.post('/api/v1/notifications/push', {
      headers: headers,
      body: body.to_json
    })

    handle_response(response)
  end

  # Масове надсилання push-сповіщень
  def send_bulk_push_notifications(notifications)
    authenticate unless @access_token

    jwt_token = create_jwt_token

    headers = {
      'Content-Type' => 'application/json',
      'Authorization' => "Bearer #{@access_token}",
      'X-Acquirer-Sign' => jwt_token
    }

    body = {
      notifications: notifications.map do |notification|
        {
          userIdentifier: notification[:user_identifier],
          title: notification[:title],
          message: notification[:message],
          data: notification[:data] || {},
          timestamp: Time.now.iso8601
        }
      end
    }

    response = self.class.post('/api/v1/notifications/push/bulk', {
      headers: headers,
      body: body.to_json
    })

    handle_response(response)
  end

  # Перевірка статусу сповіщення
  def get_notification_status(notification_id)
    authenticate unless @access_token

    jwt_token = create_jwt_token

    headers = {
      'Authorization' => "Bearer #{@access_token}",
      'X-Acquirer-Sign' => jwt_token
    }

    response = self.class.get("/api/v1/notifications/#{notification_id}/status", {
      headers: headers
    })

    handle_response(response)
  end

  private

  def handle_response(response)
    if response.success?
      {
        success: true,
        data: response.parsed_response,
        status_code: response.code
      }
    else
      {
        success: false,
        error: response.parsed_response || "HTTP Error: #{response.code}",
        status_code: response.code
      }
    end
  end
end

