require 'sinatra'
require 'httparty'
require 'json'
require 'erb'

# Enable Sinatra's built-in server for development
set :server, 'thin'

# PrivatBank API endpoint for exchange rates
PRIVATBANK_API_URL = 'https://api.privatbank.ua/p24api/pubinfo?json&exchange&coursid=5'

# Fetch exchange rates from PrivatBank API
def fetch_exchange_rates
  begin
    response = HTTParty.get(PRIVATBANK_API_URL, timeout: 10)

    if response.success?
      # Parse JSON response
      data = JSON.parse(response.body)

      # Process and organize the data
      rates = []

      data.each do |item|
        rates << {
          currency: item['ccy'],
          base_currency: item['base_ccy'],
          buy: item['buy'],
          sell: item['sale']
        }
      end

      rates
    else
      []
    end
  rescue => e
    puts "Error fetching exchange rates: #{e.message}"
    []
  end
end

# Route for the main page
get '/' do
  @rates = fetch_exchange_rates
  @last_updated = Time.now.strftime("%Y-%m-%d %H:%M:%S")

  erb :index
end

# Route for JSON API
get '/api/rates' do
  content_type :json

  rates = fetch_exchange_rates
  { 
    rates: rates,
    last_updated: Time.now.iso8601
  }.to_json
end
