```ruby
require 'httparty'
require 'json'
require 'logger'
require 'dotenv/load'

class OLXPublisher
  include HTTParty

  # Configure HTTParty
  base_uri 'https://partner.olx.ua/api/v1'
  headers 'Content-Type' => 'application/json'

  def initialize(api_key, logger = nil)
    @api_key = api_key
    @logger = logger || Logger.new(STDOUT)
    @logger.level = Logger::INFO
  end

  # Publish a new advertisement
  def publish_advertisement(ad_data)
    @logger.info("Publishing advertisement: #{ad_data[:title]}")

    begin
      response = self.class.post(
        '/ads',
        headers: {
          'Authorization' => "Bearer #{@api_key}",
          'Content-Type' => 'application/json'
        },
        body: ad_data.to_json
      )

      if response.success?
        @logger.info("Advertisement published successfully")
        JSON.parse(response.body)
      else
        @logger.error("Failed to publish advertisement: #{response.body}")
        raise "Failed to publish advertisement: #{response.body}"
      end
    rescue => e
      @logger.error("Error publishing advertisement: #{e.message}")
      raise
    end
  end

  # Update an existing advertisement
  def update_advertisement(ad_id, ad_data)
    @logger.info("Updating advertisement with ID: #{ad_id}")

    begin
      response = self.class.put(
        "/ads/#{ad_id}",
        headers: {
          'Authorization' => "Bearer #{@api_key}",
          'Content-Type' => 'application/json'
        },
        body: ad_data.to_json
      )

      if response.success?
        @logger.info("Advertisement updated successfully")
        JSON.parse(response.body)
      else
        @logger.error("Failed to update advertisement: #{response.body}")
        raise "Failed to update advertisement: #{response.body}"
      end
    rescue => e
      @logger.error("Error updating advertisement: #{e.message}")
      raise
    end
  end

  # Get advertisement details
  def get_advertisement(ad_id)
    @logger.info("Retrieving advertisement with ID: #{ad_id}")

    begin
      response = self.class.get(
        "/ads/#{ad_id}",
        headers: {
          'Authorization' => "Bearer #{@api_key}"
        }
      )

      if response.success?
        JSON.parse(response.body)
      else
        @logger.error("Failed to retrieve advertisement: #{response.body}")
        raise "Failed to retrieve advertisement: #{response.body}"
      end
    rescue => e
      @logger.error("Error retrieving advertisement: #{e.message}")
      raise
    end
  end

  # Delete an advertisement
  def delete_advertisement(ad_id)
    @logger.info("Deleting advertisement with ID: #{ad_id}")

    begin
      response = self.class.delete(
        "/ads/#{ad_id}",
        headers: {
          'Authorization' => "Bearer #{@api_key}"
        }
      )

      if response.success?
        @logger.info("Advertisement deleted successfully")
        JSON.parse(response.body)
      else
        @logger.error("Failed to delete advertisement: #{response.body}")
        raise "Failed to delete advertisement: #{response.body}"
      end
    rescue => e
      @logger.error("Error deleting advertisement: #{e.message}")
      raise
    end
  end

  # List advertisements
  def list_advertisements(page: 1, limit: 20)
    @logger.info("Listing advertisements (page: #{page}, limit: #{limit})")

    begin
      response = self.class.get(
        '/ads',
        headers: {
          'Authorization' => "Bearer #{@api_key}"
        },
        query: {
          page: page,
          limit: limit
        }
      )

      if response.success?
        JSON.parse(response.body)
      else
        @logger.error("Failed to list advertisements: #{response.body}")
        raise "Failed to list advertisements: #{response.body}"
      end
    rescue => e
      @logger.error("Error listing advertisements: #{e.message}")
      raise
    end
  end
