require 'sinatra'
require 'dry/validation'
require 'json'
require 'active_model'

# Validation modules for German tax and VAT numbers
module GermanTaxValidator
  # Validates German tax identification numbers (Steuer-ID)
  def self.validate_tax_id(tax_id)
    # Remove spaces and hyphens
    cleaned = tax_id.gsub(/[\s-]/, '')

    # Check if it's a valid format (should be 11 digits)
    return false unless cleaned.match?(/\A\d{11}\z/)

    # Check checksum using Mod 11 algorithm
    digits = cleaned.chars.map(&:to_i)
    sum = 0
    weight = 2

    # Calculate weighted sum from right to left
    (digits.length - 2).downto(0) do |i|
      sum += digits[i] * weight
      weight = weight == 10 ? 2 : weight + 1
    end

    # Calculate check digit
    remainder = sum % 11
    check_digit = 11 - remainder

    # Special case: if remainder is 1, it's invalid
    return false if remainder == 1

    # If remainder is 0, check digit should be 0
    check_digit = 0 if check_digit == 10

    # Validate the check digit
    check_digit == digits.last
  end
end

module GermanVatValidator
  # Validates German VAT numbers (VAT ID)
  def self.validate_vat_id(vat_id)
    # Remove spaces and hyphens
    cleaned = vat_id.gsub(/[\s-]/, '')

    # Check if it starts with DE (Germany country code)
    return false unless cleaned.match?(/\ADE\d{9}\z/i)

    # Remove country code and check the remaining 9 digits
    digits = cleaned[2..-1].chars.map(&:to_i)

    # The validation algorithm for German VAT numbers is complex
    # For this implementation, we'll do a basic format check
    # In a real-world application, you'd use the EU's VAT validation service

    # Just check if it's 9 digits after the country code
    digits.length == 9
  end
end

# Form validation using dry-validation
