  include Dry::Validation::Contract

  params do
    required(:tax_id).filled(:string)
    required(:vat_id).filled(:string)
  end

  rule(:tax_id) do
    key.failure('Tax ID is invalid') unless GermanTaxValidator.validate_tax_id(value)
  end

  rule(:vat_id) do
    key.failure('VAT ID is invalid') unless GermanVatValidator.validate_vat_id(value)
  end
end

# Main Sinatra application
