## Код реалізації

```ruby
require 'nokogiri'
require 'matrix'
require 'csv'

class TFIDFAnalyzer
  def initialize
    @documents = []
    @vocabulary = {}
    @idf = {}
    @tfidf_matrix = nil
  end

  # Додавання документа до набору
  def add_document(text, id = nil)
    doc = {
      id: id || @documents.length,
      text: text,
      tokens: tokenize(text)
    }
    @documents << doc
  end

  # Токенізація тексту
  def tokenize(text)
    # Видаляємо пунктуацію та переводимо в нижній регістр
    tokens = text.downcase.gsub(/[^\w\s]/, '').split(/\s+/)
    # Видаляємо порожні елементи
    tokens.reject(&:empty?)
  end

  # Обчислення TF-IDF для всіх документів
  def calculate_tfidf
    # Створюємо словник усіх унікальних токенів
    @vocabulary = {}
    @documents.each do |doc|
      doc[:tokens].each do |token|
        @vocabulary[token] = true
      end
    end

    # Обчислення IDF для кожного токена
    total_docs = @documents.length
    @idf = {}
    @vocabulary.each_key do |token|
      # Кількість документів, що містять цей токен
      docs_with_token = @documents.count { |doc| doc[:tokens].include?(token) }
      # IDF = log(загальна кількість документів / кількість документів з токеном)
      @idf[token] = Math.log(total_docs.to_f / docs_with_token.to_f)
    end

    # Створюємо TF-IDF матрицю
    @tfidf_matrix = []
    @documents.each do |doc|
      # Обчислення TF для кожного токена в документі
      tf = {}
      doc[:tokens].each do |token|
        tf[token] = tf[token].to_i + 1
      end

      # Нормалізація TF
      total_tokens = doc[:tokens].length
      tf.each do |token, count|
        tf[token] = count.to_f / total_tokens
      end

      # Обчислення TF-IDF
      tfidf = {}
      @vocabulary.each_key do |token|
        tfidf[token] = tf[token] ? tf[token] * @idf[token] : 0
      end

      @tfidf_matrix << tfidf
    end
  end

  # Отримання ключових слів для конкретного документа
  def get_keywords(doc_index, top_n = 10)
    raise "Немає TF-IDF матриці. Спочатку викличте calculate_tfidf" unless @tfidf_matrix

    tfidf_vector = @tfidf_matrix[doc_index]
    # Сортуємо за значенням TF-IDF
    sorted_words = tfidf_vector.sort_by { |token, tfidf| -tfidf }
    # Вибираємо найкращі N
    sorted_words.first(top_n).map { |token, tfidf| { token: token, tfidf: tfidf } }
  end

  # Обчислення косинусної схожості між документами
  def cosine_similarity(doc1_index, doc2_index)
    raise "Немає TF-IDF матриці. Спочатку викличте calculate_tfidf" unless @tfidf_matrix

    vector1 = @tfidf_matrix[doc1_index]
    vector2 = @tfidf_matrix[doc2_index]

    # Обчислення скалярного добутку
    dot_product = 0
    @vocabulary.each_key do |token|
      dot_product += vector1[token] * vector2[token]
    end

    # Обчислення норм
    norm1 = Math.sqrt(@vocabulary.keys.sum { |token| vector1[token]**2 })
    norm2 = Math.sqrt(@vocabulary.keys.sum { |token| vector2[token]**2 })

    # Обчислення косинусної схожості
    return 0 if norm1 == 0 || norm2 == 0
    dot_product / (norm1 * norm2)
  end

