require "httparty"
require "json"

class BinotelCall
  def initialize(api_key, api_secret)
    @api_key = api_key
    @api_secret = api_secret
    @base_url = "https://api.binotel.com/api/v4"
  end

  def call_customer(phone_number, message)
    # Authenticate and get an access token
    token = authenticate

    # Create a new call
    call_id = create_call(token, phone_number)

    # Add a voice message to the call
    add_voice_message(token, call_id, message)
  end

  private

  def authenticate
    response = HTTParty.post(
      "#{@base_url}/auth/login",
      headers: {
        "Content-Type" => "application/json"
      },
      body: {
        api_key: @api_key,
        api_secret: @api_secret
      }.to_json
    )

    JSON.parse(response.body)["access_token"]
  end

  def create_call(token, phone_number)
    response = HTTParty.post(
      "#{@base_url}/calls",
      headers: {
        "Authorization" => "Bearer #{token}",
        "Content-Type" => "application/json"
      },
      body: {
        type: "outbound",
        phone_number: phone_number
      }.to_json
    )

    JSON.parse(response.body)["call_id"]
  end

  def add_voice_message(token, call_id, message)
    response = HTTParty.post(
      "#{@base_url}/calls/#{call_id}/actions",
      headers: {
        "Authorization" => "Bearer #{token}",
        "Content-Type" => "application/json"
      },
      body: {
        action: "playAudio",
        audio: {
          type: "textToSpeech",
          text: message
        }
      }.to_json
    )

    response.success?
  end
end

