## WhatsApp API Client Implementation

```ruby
# lib/whatsapp_api_client.rb
require 'httparty'
require 'json'
require 'active_support/core_ext/hash/indifferent_access'
require 'dry-validation'

class WhatsAppAPIClient
  include HTTParty

  # Configure HTTParty
  base_uri 'https://graph.facebook.com/v17.0'
  headers 'Content-Type' => 'application/json'

  # Validation schema for template messages
  ValidationSchema = Dry::Validation.Schema do
    required(:to).filled(:string)
    required(:template_name).filled(:string)
    required(:language_code).filled(:string)
    optional(:components).array(:hash)
  end

  def initialize(access_token, phone_number_id)
    @access_token = access_token
    @phone_number_id = phone_number_id
  end

  # Send a WhatsApp template message
  def send_template_message(to, template_name, language_code, components = [])
    # Validate parameters
    result = ValidationSchema.call(
      to: to,
      template_name: template_name,
      language_code: language_code,
      components: components
    )

    if result.failure?
      raise ArgumentError, "Invalid parameters: #{result.errors}"
    end

    # Prepare the message payload
    payload = {
      messaging_product: "whatsapp",
      to: to,
      type: "template",
      template: {
        name: template_name,
        language: {
          code: language_code
        }
      }
    }

    # Add components if provided
    if components.any?
      payload[:template][:components] = components
    end

    # Send the message
    response = self.class.post(
      "/#{@phone_number_id}/messages",
      body: payload.to_json,
      headers: {
        'Authorization' => "Bearer #{@access_token}",
        'Content-Type' => 'application/json'
      }
    )

    # Handle response
    case response.code
    when 200..299
      parse_success_response(response)
    else
      parse_error_response(response)
    end
  end

  private

  def parse_success_response(response)
    data = JSON.parse(response.body)
    {
      success: true,
      message_id: data['messaging_product'] == 'whatsapp' ? data['messages'].first['id'] : nil,
      response: data
    }
  end

  def parse_error_response(response)
    data = JSON.parse(response.body)
    {
      success: false,
      error: data['error']['message'],
      error_code: data['error']['code'],
      error_subcode: data['error']['subcode'],
      response: data
    }
  end
end
