```ruby
# invoice_generator.rb
require 'pdfkit'
require 'mail'
require 'prawn'
require 'erb'
require 'sass'

class InvoiceGenerator
  def initialize
    # Configure PDFKit
    PDFKit.configure do |config|
      config.wkhtmltopdf = '/usr/local/bin/wkhtmltopdf' # Update this path if needed
    end

    # Configure mail
    Mail.defaults do
      delivery_method :smtp, {
        address: 'smtp.example.com',
        port: 587,
        user_name: 'your_username',
        password: 'your_password',
        authentication: 'plain',
        enable_starttls_auto: true
      }
    end
  end

  def generate_pdf(invoice_data, template_path = 'invoice.html.erb', output_path = 'invoice.pdf')
    # Render the HTML template
    html = render_template(template_path, invoice_data)

    # Generate PDF using PDFKit
    kit = PDFKit.new(html, page_size: 'A4', encoding: 'UTF-8')
    kit.to_file(output_path)
    output_path
  end

  def send_email(to, subject, body, pdf_path)
    mail = Mail.new do
      from    'sender@example.com'
      to      to
      subject subject
      body    body
      add_file pdf_path
    end

    mail.deliver!
  end

  private

  def render_template(template_path, data)
    # Use ERB to render the template
    template = File.read(template_path)
    ERB.new(template).result(binding)
  end
end

