```ruby
require 'quickbooks'
require 'logger'
require 'oj'

class QuickBooksExporter
  def initialize(config)
    @config = config
    @logger = Logger.new(config[:log_file] || STDOUT)
    @logger.level = Logger::INFO
  end

  def export_invoices(payment_data)
    QBClient.new(
      @config[:client_id],
      @config[:client_secret],
      @config[:realm_id],
      @config[:refresh_token]
    ).tap do |client|
      payment_data.each do |payment|
        export_payment_as_invoice(client, payment)
      end
    end
  end

  private

  def export_payment_as_invoice(client, payment)
    @logger.info "Processing payment: #{payment[:id]}"

    invoice = build_invoice(payment)
    begin
      response = client.invoice.create(invoice: invoice)

      if response.success?
        @logger.info "Successfully exported invoice: #{response.data['Invoice']['DocNumber']}"
        update_payment_status(payment, 'exported')
      else
        @logger.error "Failed to export invoice: #{response.error_message}"
        update_payment_status(payment, 'failed', response.error_message)
      end
    rescue StandardError => e
      @logger.error "Error exporting invoice: #{e.message}"
      update_payment_status(payment, 'failed', e.message)
    end
  end

  def build_invoice(payment)
    {
      customer: {
        given_name: payment[:customer_name],
        family_name: '', # Add if available
        DisplayName: payment[:customer_name],
        PrimaryEmailAddr: {
          Address: payment[:customer_email] || ''
        }
      },
      line: [{
        amount: payment[:amount],
        description: "Payment #{payment[:id]}",
        detail_type: 'SalesItemLineDetail',
        sales_item_line_detail: {
          item_ref: {
            name: 'Payment',
            value: '1' # You should use actual item ID from QuickBooks
          },
          qty: 1,
          unit_price: payment[:amount]
        }
      }],
      txn_date: Time.now.utc.iso8601,
      doc_number: "PAY-#{payment[:id]}",
      payment_type: 'CreditCard',
      total_amount: payment[:amount]
    }
  end

  def update_payment_status(payment, status, error_message = nil)
    # Implement your logic to update payment status in your system
    # This could be a database update, API call, etc.
    @logger.debug "Updating payment #{payment[:id]} status to #{status}"
  end
end

